import json


def append_public_banking_guide(doc, root, add_table, add_code_block):
    report = json.loads((root / 'reports/public_banking_corpus.json').read_text(encoding='utf-8'))
    probe = json.loads((root / 'reports/public_banking_probe.json').read_text(encoding='utf-8'))
    doc.add_page_break()
    doc.add_heading('Открытый банковский корпус и экспертная разметка', level=1)
    doc.add_paragraph('После демонстрационного агента мы подготовили воспроизводимый исследовательский корпус из официальных FAQ CFPB. Собраны 12 материалов, 11 допущены к локальным экспериментам, один помещён в карантин. Подготовлены 26 черновиков запросов для ручного разбора. Экспертная разметка и бизнес согласование пока не выполнены. Следующий обоснованный шаг — получить независимые вопросы и проверку специалиста, затем калибровать отказ и оценивать агента на новом holdout.')
    doc.add_heading('Почему выбран этот источник', level=2)
    doc.add_paragraph('CFPB публикует объяснения типовых финансовых ситуаций: спорные операции, автоматические платежи, закрытие счёта, потерянные карты и комиссии. Это тематически близко BANKING77, но задачи различаются. Классификатор предсказывает intent обращения, retrieval ищет подтверждающий текст. FAQ не заменяет банковские регламенты, персональные данные или доступ к операциям клиента.')
    doc.add_paragraph('Материалы относятся к США и написаны на английском. Переносить их правовые сроки и условия на Россию нельзя. Корпус имеет jurisdiction=US, language=en и approval_scope=research_only. Источник принадлежит CFPB; ответственный за применение в конкретном банке ещё не назначен. Известный издатель не означает бизнес согласование нашей системы.')
    doc.add_paragraph('Политика сайта относит созданный CFPB текст к public domain, но отдельно исключает материалы внешних правообладателей и ограничивает использование обозначений ведомства. Мы сохраняем текст FAQ и ссылки на первоисточник, без логотипов и внешних материалов. Снимок политики и его SHA-256 включены в sources.json. Для другого сайта проверку условий использования придётся провести заново.')
    doc.add_heading('Как получены и сохранены материалы', level=2)
    doc.add_paragraph('Прямая HTTP-загрузка вернула 403. Вместо обхода защиты сохранён текст, доступный через веб reader. Файлы snapshots являются извлечённым текстом, а не исходным HTML. Это ограничение явно записано в provenance. Хеш подтверждает неизменность нашего снимка после сохранения, но не является цифровой подписью издателя и не доказывает полноту страницы.')
    doc.add_paragraph('Источники перечислены в data/public_banking/sources.json: официальный URL, ID, тема и хеш снимка. Функция build_bundle проверяет домен, HTTPS, формат ID, уникальность, контрольные суммы и политику повторного использования. Парсер требует заголовок, дату Last reviewed, завершающий маркер Page last modified и содержательный текст. Меню и footer удаляются; заголовок остаётся метаданными и не входит в индексируемое тело статьи.')
    add_code_block(doc, "python scripts/build_public_banking.py\npython scripts/probe_public_banking.py")
    doc.add_paragraph('Первый скрипт строит корпус из сохранённых снимков без сети. Второй требует окружение с torch и sentence-transformers и локальный кеш закреплённой версии multilingual-e5-small. Его запуск не обучает модель и не использует закрытый holdout. Ноутбук 09_public_banking_review.ipynb позволяет просмотреть статьи, отчёты и черновики без повторного dense эксперимента.')
    add_table(doc, ['Поле', 'Значение и смысл'], [
        ('updated_at', 'Дата Last reviewed у издателя; не дата скачивания и не гарантия актуальности'),
        ('retrieved_at', 'Дата фиксации исследовательского снимка 17 ноября 2026 года'),
        ('snapshot_sha256', 'Контроль неизменности локального текста'),
        ('status и approval_scope', 'Исследовательский доступ отдельно от разрешения обслуживать пользователя'),
        ('expert_review', 'False до реальной проверки специалистом')])
    doc.add_heading('Что обнаружила проверка актуальности', level=2)
    doc.add_paragraph(f"У {report['review_due']} из 12 страниц дата проверки старше года. Это повод для повторной проверки, а не автоматическое доказательство ошибки. Более существенное расхождение найдено в cfpb_1023 о доступности средств: снимок содержит суммы 225 и 5525 долларов, тогда как официальное обновление Regulation CC указывает 275 и 6725 долларов с 1 июля 2025 года. Даже свежая дата в шапке FAQ не устраняет это расхождение.")
    doc.add_paragraph('Мы сохранили исходный снимок и исключили статью из research_articles.jsonl. Автоматическая замена чисел скрыла бы происхождение исправления и потребовала бы правовой проверки применимости. Состояние quarantined записано в candidates.jsonl и отчёте. Карантин снимается отдельным решением после проверки источника и новой версии корпуса; в этом этапе он не снят.')
    doc.add_paragraph('Подтверждение порогов: https://www.consumerfinance.gov/rules-policy/final-rules/availability-funds-and-collection-checks-regulation-cc-threshold-adjustments/ и https://www.federalreserve.gov/frrs/regulations/section-22911-adjustment-of-dollar-amounts.htm . Это описание найденного противоречия в данных проекта, а не персональная финансовая рекомендация.')
    doc.add_heading('Как отделён эксперимент от рабочего API', level=2)
    add_code_block(doc, "load_documents(path)\nload_documents(path, purpose='research')")
    doc.add_paragraph('По умолчанию загрузчик требует approved и отвергает approval_scope=research_only. Поэтому простая смена status не переносит исследовательский документ в обслуживание. Явный purpose=research разрешает исследовательские материалы с указанной юрисдикцией; quarantined по-прежнему запрещён. Это защита от случайного смешивания режимов, а не система управления полномочиями против человека, который может изменить весь код и данные.')
    doc.add_paragraph('Конфигурация действующего API не переключалась на новый корпус. Старые пороги BM25 относятся к старой базе и не переносятся на CFPB. Пороги dense и RRF также не подобраны. До экспертной проверки нельзя включать новый поиск в prepare_answer только потому, что top-1 выглядит правдоподобно.')
    doc.add_heading('Что именно измерено в поиске', level=2)
    doc.add_paragraph('В пробе 11 FAQ заголовков используются как запросы, а исходная статья — как известная пара. Это слабая разметка publisher_heading_pair. Другие статьи тоже могут быть полезными, но полного перечня релевантности нет. Поэтому показатели названы primary_source_hit и primary_source_mrr, а не полноценный Recall по всем релевантным статьям или качество ответов клиентам.')
    doc.add_paragraph('После разбиения получено 24 фрагмента из 11 статей. Результаты объединяются по ID статьи до оценки первых пяти позиций. Параметры перенесены из демонстрационного эксперимента без подбора: BM25 k1=1 и b=0.3, глубина ветвей RRF 4, константа 60. Dense использует multilingual-e5-small с закреплённой ревизией. RRF суммирует 1/(60+rank) по ветвям; численные BM25 и cosine score напрямую не складываются.')
    add_table(doc, ['Метод', 'Источник на первом месте', 'Источник в первых пяти', 'MRR источника'], [
        (name, f"{row['primary_source_hit_at_1']:.3f}", f"{row['primary_source_hit_at_5']:.3f}", f"{row['primary_source_mrr_at_5']:.3f}")
        for name, row in probe['metrics'].items()])
    doc.add_paragraph('BM25 дал 8 из 11 первых позиций, dense и hybrid RRF — 10 из 11. На этих вопросах RRF не превзошёл dense. Выборка мала и близка к формулировкам издателя; статистическую значимость и превосходство на реальных обращениях мы не заявляем. Время в отчёте измерено локально после подготовки индекса и не является HTTP SLA или оценкой холодного запуска. Реранкер не возвращался: прежнее ухудшение остаётся основанием держать его вне текущего решения.')
    doc.add_heading('Как получить пригодную экспертную разметку', level=2)
    doc.add_paragraph('annotation_drafts.jsonl содержит по два AI черновика на 11 допустимых тем и четыре граничных отрицательных вопроса: персональный баланс, секретный PIN, конкретный банковский тариф и применение российского права. Всего 26 строк. Предложенные метки хранятся отдельно; relevant_document_ids, split и сведения о проверке пусты. Эти вопросы нельзя выдавать за реальные обращения или экспертный gold.')
    doc.add_paragraph('Сначала специалист читает вопрос и весь корпус, выбирает все подходящие статьи либо пустой список при отсутствии ответа, отмечает неоднозначность и причины. Ноутбук по умолчанию скрывает предложенные AI метки, чтобы уменьшить привязку к подсказке. Затем можно открыть предложения и разобрать расхождения. Спорные случаи требуют согласования; если вопрос нельзя однозначно оценить, его следует переписать или исключить с сохранением причины.')
    doc.add_paragraph('Для holdout нужны новые вопросы, написанные человеком, который не подбирает retrieval параметры. Другой специалист проверяет метки. Перефразы одной потребности получают общий query_group_id и целиком попадают только в один split. В обоих splits нужны вопросы с ответом и без ответа. До выбора параметров фиксируются корпус, группы, состав splits и критерии качества. Изменение флагов у AI черновиков не создаёт независимого holdout.')
    add_code_block(doc, "python scripts/export_banking_review.py --input work/reviewed_queries.jsonl --output-dir work/banking_review_v1")
    doc.add_paragraph('Экспорт проверяет совпадение SHA-256 корпуса, approved разметку, reviewer_role=domain_expert, дату, ID статей, отсутствие дублей и пересечения групп. Для holdout требуются human_authored и разные author_id и reviewer_id. Запись разрешена только в новый каталог work, исключённый из Git. Экспорт не утверждает источники для обслуживания. Поля reviewer являются свидетельствами, предоставленными людьми; код не проверяет их личность, квалификацию или фактическую независимость.')
    doc.add_heading('Проверки и границы готовности', level=2)
    doc.add_paragraph('Итоговая проверка проекта проходит 68 тестов. Новые проверки покрывают исследовательский режим загрузки, запрет обхода через смену статуса, карантин, неполный снимок, изменение контрольной суммы, черновую разметку, неподходящий holdout и пересечение смысловых групп. Ноутбук выполняется отдельно в Jupyter. Эти проверки защищают формат и правила pipeline; они не подтверждают правовую корректность FAQ и качество консультаций.')
    doc.add_paragraph('Далее: реальная проверка источников и разметки, фиксация calibration и нового holdout, подбор порога отказа только на calibration, однократная итоговая оценка, затем проверка действий и цитат агента на том же согласованном корпусе. Развёртывание с этим корпусом требует отдельного решения о допустимой юрисдикции, источниках и ответственном владельце. Техническая подготовка текущего этапа завершена; человеческая экспертиза остаётся обязательным входом следующего.')
    doc.add_heading('Вопросы для собеседования о качестве данных', level=2)
    for question, answer in [
        ('Почему официальный источник может попасть в карантин', 'Издатель заслуживает внимания, но отдельный текст может устареть или противоречить более точному нормативному источнику. Мы сохраняем provenance и исключаем сомнительный материал до разрешения конфликта.'),
        ('Почему нельзя назвать 10 из 11 качеством агента', 'Здесь измерено восстановление известной FAQ статьи по её заголовку. Нет независимых клиентских запросов, полной разметки релевантности и проверки действий или ответов агента.'),
        ('Зачем разделять calibration и holdout по смысловым группам', 'Почти одинаковые перефразы по обе стороны дают оптимистичную оценку. Группа переносится целиком, а holdout не используется для выбора параметров.'),
        ('Почему RRF может не улучшить dense', 'Слияние помогает при взаимодополняющих ошибках. Слабая lexical ветвь может не добавить полезной информации или ухудшить порядок. Это проверяется экспериментом.'),
        ('Что подтверждает SHA 256', 'Неизменность конкретных байтов относительно зафиксированного хеша. Он не подтверждает авторство, актуальность, юридическую применимость или независимость разметчика.')]:
        doc.add_paragraph(question, style='Heading 3')
        doc.add_paragraph(answer)
    doc.add_paragraph('Политика использования материалов CFPB: https://www.consumerfinance.gov/privacy/website-privacy-policy/ . Точные URL всех FAQ и контрольные суммы: data/public_banking/sources.json. Результаты: reports/public_banking_corpus.json и reports/public_banking_probe.json. Код: src/data/public_banking.py и scripts/export_banking_review.py.')
